#!/bin/sh
set -eu
root=${1:?"usage: ROLLBACK.sh TARGET_REPO_COPY"}
tmp=${TMPDIR:-/tmp}/gsa-rollback-$$.patch
trap 'rm -f "$tmp"' EXIT HUP INT TERM
python3 - "$tmp" <<'PYROLLBACK'
from pathlib import Path
import base64,gzip,sys
payload = """"""
Path(sys.argv[1]).write_bytes(gzip.decompress(base64.b64decode(payload)))
PYROLLBACK
(cd "$root" && git apply --reverse "$tmp")
echo "rollback restored baseline bytes in $root"
